"""Text-to-SQL harness: draft -> execute/verify -> one targeted repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL_EQ = re.compile(r"([A-Za-z_][\w.]*)\s*=\s*'([^']*)'")
LITERAL_LIKE = re.compile(r"([A-Za-z_][\w.]*)\s+(?:NOT\s+)?LIKE\s+'([^']*)'", re.I)
IN_LIST = re.compile(r"\bIN\s*\(([^()']*'[^)]*)\)", re.I)
QUOTED = re.compile(r"'([^']*)'")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    t = (text or "").strip()
    m = re.search(r"(?is)\bSELECT\b.*", t)
    if m:
        return m.group(0).rstrip(";").strip()
    return t.rstrip(";").strip()


def _looks_complete(sql):
    s = (sql or "").strip()
    if not s or not re.match(r"(?is)^(SELECT|WITH)\b", s):
        return False
    if s.count("(") != s.count(")") or s.count("'") % 2 != 0:
        return False
    # truncated tail like a dangling operator/comma
    if re.search(r"(?is)(,|\bAND|\bOR|\bBY|\bSELECT|\bWHERE|=|<|>)\s*$", s):
        return False
    return True


def _question_literals(question):
    return set(m.lower() for m in re.findall(r"[\"']([^\"']+)[\"']", question or ""))


def _probe_values(env, sql):
    """For text literals used as filters, fetch actual stored values of that column."""
    notes = []
    seen = set()
    pairs = LITERAL_EQ.findall(sql) + LITERAL_LIKE.findall(sql)
    for _, body in IN_LIST.findall(sql):
        pass
    for col, val in pairs:
        bare = col.split(".")[-1]
        key = (bare.lower(), val.lower())
        if key in seen or len(val) < 3 or val.isdigit():
            continue
        seen.add(key)
        probe = (
            "SELECT DISTINCT {c} FROM {t} WHERE {c} LIKE '%{frag}%' LIMIT 8"
        )
        # find a table containing this column from the schema-less route:
        # try each table alias source via a cheap sqlite_master scan is not possible
        # without table names; instead reuse tables mentioned in the draft SQL.
        frag = re.sub(r"[%_']", "", val).strip()
        frag = frag[:24]
        if not frag:
            continue
        for tbl in _tables_in(sql):
            r = env.execute(probe.format(c=bare, t=tbl, frag=frag.replace("'", "''")), max_rows=8)
            if r.get("ok") and r.get("rows"):
                vals = [str(row[0]) for row in r["rows"]]
                notes.append(f"Column `{bare}` in table `{tbl}` actually stores values like: {vals}")
                break
        if len(notes) >= 4:
            break
    return notes


def _tables_in(sql):
    tbls = re.findall(r"(?i)\b(?:FROM|JOIN)\s+([A-Za-z_]\w*)", sql)
    out = []
    for t in tbls:
        if t not in out:
            out.append(t)
    return out


def _result_note(res):
    if not res.get("ok"):
        return f"EXECUTION ERROR: {res.get('error')}"
    rows = res.get("rows") or []
    cols = res.get("columns") or []
    head = rows[:5]
    return (
        f"Query ran OK: {res.get('n_rows')} rows x {len(cols)} cols. "
        f"Columns: {cols}. First rows: {head}"
    )


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc:
        user += f"\n\nColumn descriptions:\n{desc[:2000]}"

    sys_msg = {"role": "system", "content": env.prompt("system_prompt.md")}
    budget = env.config.get("max_tokens", 1200)
    reply = env.chat([sys_msg, {"role": "user", "content": user}], max_tokens=budget)
    sql = extract_sql(reply)

    complete = _looks_complete(sql)
    res = env.execute(sql, max_rows=20) if complete else {"ok": False, "error": "draft SQL missing or truncated"}

    q_lits = _question_literals(task.get("question", ""))
    sql_lits = set(v.lower() for v in QUOTED.findall(sql))
    used_question_literal = bool(q_lits & sql_lits)

    needs_repair = (
        not complete
        or not res.get("ok")
        or (res.get("n_rows", 0) == 0 and used_question_literal)
    )

    if not needs_repair:
        return {"sql": sql}

    # Second (final) call: targeted repair with execution evidence.
    feedback = [f"Your draft query was:\n```sql\n{sql}\n```", _result_note(res)]
    if complete and (not res.get("ok") or res.get("n_rows", 0) == 0):
        probes = _probe_values(env, sql)
        if probes:
            feedback.append(
                "Actual stored values for the columns you filtered on:\n" + "\n".join(probes)
            )
        feedback.append(
            "If the result is empty or errors, the likely cause is a string literal that does not "
            "match the stored data (spelling, plural, case, punctuation, trailing spaces). "
            "Rewrite the filter tolerantly (LIKE '%core phrase%' with lower/trim) using the actual "
            "values shown above when available."
        )
    if not complete:
        feedback.append(
            "The draft was truncated or is not a single complete SELECT. Answer the ORIGINAL question "
            "directly with one short, complete query — no analysis, no extra statistics."
        )
    feedback.append(
        "Re-check against the question: correct projection (only requested columns; whole rows if no "
        "attributes named), ANY→MAX / ALL→MIN for comparisons, negation scope (NOT EXISTS over the "
        "filtered set), INNER vs LEFT join, and 'both A and B' via HAVING COUNT(DISTINCT ...) = 2.\n"
        "Return the corrected final query in one ```sql block."
    )
    repair_user = user + "\n\n---\n" + "\n\n".join(feedback)
    reply2 = env.chat([sys_msg, {"role": "user", "content": repair_user}], max_tokens=budget)
    sql2 = extract_sql(reply2)

    if _looks_complete(sql2):
        res2 = env.execute(sql2, max_rows=20)
        if res2.get("ok"):
            # Prefer the repair when the draft failed outright; when the draft ran but
            # returned 0 rows on question literals, prefer non-empty repair.
            if not res.get("ok") or not complete:
                return {"sql": sql2}
            if res.get("n_rows", 0) == 0 and res2.get("n_rows", 0) > 0:
                return {"sql": sql2}
            if res.get("n_rows", 0) == 0 and used_question_literal:
                return {"sql": sql2}
    return {"sql": sql if complete else (sql2 or sql)}

